package noise

import (
	"bytes"
	"crypto/ecdh"
	"encoding/hex"
	"testing"
)

func unhex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

// Golden encodings generated by the Python reference implementation.
func TestEnvelopeGoldens(t *testing.T) {
	reqFrame, err := EncodeServiceFrame(RequestFrame(7, &ApplicationRequest{
		Verb: "POST", Path: "/chat/stream",
		Headers: []Header{{Key: "Content-Type", Value: "application/json"}},
		Body:    []byte(`{"a":1}`), EndBody: true,
	}))
	if err != nil {
		t.Fatal(err)
	}
	if want := unhex(t, "080712410a04504f5354120c2f636861742f73747265616d1a200a0c436f6e74656e742d5479706512106170706c69636174696f6e2f6a736f6e22077b2261223a317d2801"); !bytes.Equal(reqFrame, want) {
		t.Errorf("request frame = %x, want %x", reqFrame, want)
	}
	decoded, err := DecodeServiceFrame(reqFrame)
	if err != nil {
		t.Fatal(err)
	}
	if decoded.Kind != FrameRequest || decoded.StreamID != 7 || decoded.Request.Verb != "POST" ||
		decoded.Request.Path != "/chat/stream" || !decoded.Request.EndBody ||
		string(decoded.Request.Body) != `{"a":1}` || len(decoded.Request.Headers) != 1 ||
		decoded.Request.Headers[0] != (Header{Key: "Content-Type", Value: "application/json"}) {
		t.Errorf("decoded request = %+v", decoded)
	}

	svcReq, err := EncodeServiceRequest(&ServiceRequest{Service: ServiceDaemon, Payload: []byte("hello")})
	if err != nil {
		t.Fatal(err)
	}
	if want := unhex(t, "120568656c6c6f"); !bytes.Equal(svcReq, want) {
		t.Errorf("service request = %x, want %x", svcReq, want)
	}
	svcReqVault, err := EncodeServiceRequest(&ServiceRequest{Service: ServiceVault})
	if err != nil {
		t.Fatal(err)
	}
	if want := unhex(t, "0802"); !bytes.Equal(svcReqVault, want) {
		t.Errorf("service request vault = %x, want %x", svcReqVault, want)
	}

	svcResp, err := EncodeServiceResponse(&ServiceResponse{Payload: []byte("world")})
	if err != nil {
		t.Fatal(err)
	}
	if want := unhex(t, "0a05776f726c64"); !bytes.Equal(svcResp, want) {
		t.Errorf("service response = %x, want %x", svcResp, want)
	}
	svcRespEmpty, err := EncodeServiceResponse(&ServiceResponse{})
	if err != nil {
		t.Fatal(err)
	}
	if len(svcRespEmpty) != 0 {
		t.Errorf("empty service response = %x, want empty", svcRespEmpty)
	}

	resetFrame, err := EncodeServiceFrame(ResetFrame(9, &Reset{Code: ResetCancelled, Reason: "bye"}))
	if err != nil {
		t.Fatal(err)
	}
	if want := unhex(t, "08092a0708011203627965"); !bytes.Equal(resetFrame, want) {
		t.Errorf("reset frame = %x, want %x", resetFrame, want)
	}

	chunkFrame, err := EncodeServiceFrame(BodyChunkFrame(3, &BodyChunk{Data: []byte("xy"), EndBody: true}))
	if err != nil {
		t.Fatal(err)
	}
	if want := unhex(t, "080322060a0278791001"); !bytes.Equal(chunkFrame, want) {
		t.Errorf("body chunk frame = %x, want %x", chunkFrame, want)
	}
}

func TestNoiseFrameGoldens(t *testing.T) {
	frame, err := EncodeNoiseFrame(NoiseTransportFrame{ChunkID: 5, ChunkIndex: 0, TotalChunks: 1, Payload: []byte("abc")})
	if err != nil {
		t.Fatal(err)
	}
	if want := unhex(t, "080518012203616263"); !bytes.Equal(frame, want) {
		t.Errorf("frame = %x, want %x", frame, want)
	}
	neg, err := EncodeNoiseFrame(NoiseTransportFrame{ChunkID: -3, ChunkIndex: 2, TotalChunks: 4})
	if err != nil {
		t.Fatal(err)
	}
	if want := unhex(t, "08fdffffffffffffffff0110021804"); !bytes.Equal(neg, want) {
		t.Errorf("negative frame = %x, want %x", neg, want)
	}
	back, err := DecodeNoiseFrame(neg)
	if err != nil {
		t.Fatal(err)
	}
	if back.ChunkID != -3 || back.ChunkIndex != 2 || back.TotalChunks != 4 || len(back.Payload) != 0 {
		t.Errorf("decoded = %+v", back)
	}
}

func TestCipherStateGolden(t *testing.T) {
	key := make([]byte, 32)
	for i := range key {
		key[i] = byte(i)
	}
	state := NewCipherState()
	if err := state.InitializeKey(key); err != nil {
		t.Fatal(err)
	}
	ct0, err := state.EncryptWithAD([]byte("ad"), []byte("hello"))
	if err != nil {
		t.Fatal(err)
	}
	if want := unhex(t, "66d9d9b2da11bae424ce671b6e7ef04a4d98656a32"); !bytes.Equal(ct0, want) {
		t.Errorf("nonce 0 ciphertext = %x, want %x", ct0, want)
	}
	ct1, err := state.EncryptWithAD([]byte("ad"), []byte("hello"))
	if err != nil {
		t.Fatal(err)
	}
	if want := unhex(t, "7db3d3902b793324921311d81c6afa5c3c84fff6d3"); !bytes.Equal(ct1, want) {
		t.Errorf("nonce 1 ciphertext = %x, want %x", ct1, want)
	}

	peer := NewCipherState()
	if err := peer.InitializeKey(key); err != nil {
		t.Fatal(err)
	}
	pt, err := peer.DecryptWithAD([]byte("ad"), ct0)
	if err != nil || string(pt) != "hello" {
		t.Fatalf("decrypt = %q, %v", pt, err)
	}
	// A bad tag poisons the state.
	peer2 := NewCipherState()
	_ = peer2.InitializeKey(key)
	bad := append([]byte(nil), ct0...)
	bad[0] ^= 1
	if _, err := peer2.DecryptWithAD([]byte("ad"), bad); err == nil {
		t.Fatal("bad tag accepted")
	}
	if _, err := peer2.DecryptWithAD([]byte("ad"), ct0); err == nil {
		t.Fatal("poisoned state accepted more input")
	}
	// Unkeyed states pass through.
	plain := NewCipherState()
	out, err := plain.EncryptWithAD(nil, []byte("data"))
	if err != nil || string(out) != "data" {
		t.Fatalf("unkeyed passthrough = %q, %v", out, err)
	}
}

func fixedKey(t *testing.T, fill byte) *x25519KeyPair {
	t.Helper()
	priv, err := ecdh.X25519().NewPrivateKey(bytes.Repeat([]byte{fill}, 32))
	if err != nil {
		t.Fatal(err)
	}
	return &x25519KeyPair{privateKey: priv, publicBytes: priv.PublicKey().Bytes()}
}

// The full handshake with fixed keys 0x11/0x22/0x33/0x44 (in generation
// order) must reproduce the Python reference byte-for-byte.
func TestHandshakeGolden(t *testing.T) {
	queue := []*x25519KeyPair{fixedKey(t, 0x11), fixedKey(t, 0x22), fixedKey(t, 0x33), fixedKey(t, 0x44)}
	idx := 0
	original := generateX25519KeyPair
	generateX25519KeyPair = func() (*x25519KeyPair, error) {
		k := queue[idx%len(queue)]
		idx++
		return k, nil
	}
	defer func() { generateX25519KeyPair = original }()

	initiator := NewInitiator()
	responder := NewResponder(nil)
	if err := initiator.Initialize(); err != nil {
		t.Fatal(err)
	}
	if err := responder.Initialize(); err != nil {
		t.Fatal(err)
	}
	m1, err := initiator.WriteMessage1()
	if err != nil {
		t.Fatal(err)
	}
	if want := unhex(t, "7b4e909bbe7ffe44c465a220037d608ee35897d31ef972f07f74892cb0f73f13"); !bytes.Equal(m1, want) {
		t.Errorf("m1 = %x, want %x", m1, want)
	}
	m2, err := responder.ReadMessage1AndWriteMessage2(m1)
	if err != nil {
		t.Fatal(err)
	}
	if want := unhex(t, "0faa684ed28867b97f4a6a2dee5df8ce974e76b7018e3f22a1c4cf2678570f2083be4718bc8739c3ea26ed6075c008d2f47a152fcbe9837641dc39e08b096889b7b97092f86c82d33ab49d34de944bd6a1d11d13912035c9c069d16f946e55fd"); !bytes.Equal(m2, want) {
		t.Errorf("m2 = %x, want %x", m2, want)
	}
	payload, err := initiator.ReadMessage2(m2)
	if err != nil {
		t.Fatal(err)
	}
	if len(payload) != 0 {
		t.Errorf("m2 payload = %x, want empty", payload)
	}
	m3, err := initiator.WriteMessage3()
	if err != nil {
		t.Fatal(err)
	}
	if want := unhex(t, "fd1098a9346acf3d47fa7ad40180f1554b9d148a5cec2c67d775374d444c62c8c0f355af97d6d5449d918ecf367b6c0d46e39fcccb00a21770fa0d6a84f68a7e"); !bytes.Equal(m3, want) {
		t.Errorf("m3 = %x, want %x", m3, want)
	}
	if err := responder.ReadMessage3(m3); err != nil {
		t.Fatal(err)
	}
	if want := unhex(t, "5038a31c611d8d2ac0e82a941fc4373f2f3c25d189536cf60183fe2010c5eaeb"); !bytes.Equal(initiator.HandshakeHash(), want) {
		t.Errorf("handshake hash = %x, want %x", initiator.HandshakeHash(), want)
	}
	ic1, _, err := initiator.Split()
	if err != nil {
		t.Fatal(err)
	}
	_, rrecv, err := responder.Split()
	if err != nil {
		t.Fatal(err)
	}
	ct, err := ic1.EncryptWithAD(nil, []byte("hello"))
	if err != nil {
		t.Fatal(err)
	}
	if want := unhex(t, "5d868fc68163685c864419e18040590f44b9afd89b"); !bytes.Equal(ct, want) {
		t.Errorf("transport ciphertext = %x, want %x", ct, want)
	}
	pt, err := rrecv.DecryptWithAD(nil, ct)
	if err != nil || string(pt) != "hello" {
		t.Fatalf("responder decrypt = %q, %v", pt, err)
	}
}

func TestHandshakeRandomAndTransportRoundTrip(t *testing.T) {
	initiator := NewInitiator()
	responder := NewResponder([]byte("server payload"))
	if err := initiator.Initialize(); err != nil {
		t.Fatal(err)
	}
	if err := responder.Initialize(); err != nil {
		t.Fatal(err)
	}
	m1, err := initiator.WriteMessage1()
	if err != nil {
		t.Fatal(err)
	}
	m2, err := responder.ReadMessage1AndWriteMessage2(m1)
	if err != nil {
		t.Fatal(err)
	}
	payload, err := initiator.ReadMessage2(m2)
	if err != nil {
		t.Fatal(err)
	}
	if string(payload) != "server payload" {
		t.Fatalf("m2 payload = %q", payload)
	}
	if initiator.RemoteStaticPublicKey() == nil {
		t.Fatal("no remote static key after m2")
	}
	m3, err := initiator.WriteMessage3()
	if err != nil {
		t.Fatal(err)
	}
	if err := responder.ReadMessage3(m3); err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(initiator.HandshakeHash(), responder.HandshakeHash()) {
		t.Fatal("handshake hashes differ")
	}
	isend, irecv, err := initiator.Split()
	if err != nil {
		t.Fatal(err)
	}
	rsend, rrecv, err := responder.Split()
	if err != nil {
		t.Fatal(err)
	}
	client := NewTransport(isend, irecv)
	server := NewTransport(rsend, rrecv)

	// Client -> server: a complete HTTP request, fed frame by frame.
	sent, err := client.EncryptHTTPRequest("POST", "/chat/stream", []byte(`{"x":1}`), nil,
		[]Header{{Key: "Content-Type", Value: "application/json"}})
	if err != nil {
		t.Fatal(err)
	}
	if sent.StreamID != 1 {
		t.Fatalf("first stream id = %d, want 1", sent.StreamID)
	}
	var gotFrame *ServiceFrame
	for _, frameBytes := range sent.Frames {
		plain, err := server.recv.DecryptWithAD(nil, frameBytes)
		if err != nil {
			t.Fatal(err)
		}
		reassembled, err := server.decoder.Decode(plain)
		if err != nil {
			t.Fatal(err)
		}
		if reassembled == nil {
			continue
		}
		gotFrame, err = DecodeRequestEnvelope(reassembled)
		if err != nil {
			t.Fatal(err)
		}
	}
	if gotFrame == nil || gotFrame.Kind != FrameRequest || gotFrame.Request.Verb != "POST" ||
		gotFrame.Request.Path != "/chat/stream" || string(gotFrame.Request.Body) != `{"x":1}` ||
		!gotFrame.Request.EndBody {
		t.Fatalf("server decoded = %+v", gotFrame)
	}

	// Server -> client: a response envelope, encrypted with the server's
	// send state and chunked like the transport does.
	responseBytes, err := EncodeResponseEnvelope(ResponseFrame(sent.StreamID,
		&ApplicationResponse{Status: 200, Body: []byte(`{"ok":true}`), EndBody: true}))
	if err != nil {
		t.Fatal(err)
	}
	protoFrames, err := EncodeNoiseFrames(responseBytes, nil)
	if err != nil {
		t.Fatal(err)
	}
	var decoded *DecryptedFrame
	for _, pf := range protoFrames {
		ct, err := rsend.EncryptWithAD(nil, pf)
		if err != nil {
			t.Fatal(err)
		}
		decoded, err = client.DecryptFrame(ct)
		if err != nil {
			t.Fatal(err)
		}
	}
	if decoded == nil || decoded.Kind != FrameResponse || decoded.Response.Status != 200 ||
		string(decoded.Response.Body) != `{"ok":true}` {
		t.Fatalf("client decoded = %+v", decoded)
	}

	// A request frame from the server is a protocol error and kills the
	// transport.
	requestBytes, err := EncodeResponseEnvelope(RequestFrame(9, &ApplicationRequest{Verb: "GET", Path: "/x"}))
	if err != nil {
		t.Fatal(err)
	}
	ct, err := rsend.EncryptWithAD(nil, requestBytes)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := client.DecryptFrame(ct); err == nil {
		t.Fatal("server request frame accepted")
	}
	if !client.Dead() {
		t.Fatal("transport not dead after protocol error")
	}
}

func TestLowOrderPointsRejected(t *testing.T) {
	priv, err := ecdh.X25519().GenerateKey(bytes.NewReader(bytes.Repeat([]byte{7}, 64)))
	if err != nil {
		t.Fatal(err)
	}
	for _, point := range x25519LowOrderPoints {
		if _, err := x25519DH(priv, point); err == nil {
			t.Errorf("low-order point %x accepted", point[:4])
		}
	}
	if _, err := x25519DH(priv, make([]byte, 31)); err == nil {
		t.Error("31-byte public key accepted")
	}
}

func TestFrameDecoderPoisonAndChunks(t *testing.T) {
	payload := bytes.Repeat([]byte("z"), MaxChunkPayload*2+10)
	frames, err := EncodeNoiseFrames(payload, nil)
	if err != nil {
		t.Fatal(err)
	}
	if len(frames) != 3 {
		t.Fatalf("frames = %d, want 3", len(frames))
	}
	decoder := NewNoiseFrameDecoder()
	var out []byte
	for _, f := range frames {
		out, err = decoder.Decode(f)
		if err != nil {
			t.Fatal(err)
		}
	}
	if !bytes.Equal(out, payload) {
		t.Fatal("reassembled payload differs")
	}
	// A duplicate chunk poisons the decoder.
	id := int64(42)
	f0, _ := EncodeNoiseFrames([]byte("hello world"), &id)
	decoder2 := NewNoiseFrameDecoder()
	single, _ := EncodeNoiseFrame(NoiseTransportFrame{ChunkID: 7, ChunkIndex: 0, TotalChunks: 2, Payload: []byte("a")})
	if _, err := decoder2.Decode(single); err != nil {
		t.Fatal(err)
	}
	if _, err := decoder2.Decode(single); err == nil {
		t.Fatal("duplicate chunk accepted")
	}
	if _, err := decoder2.Decode(f0[0]); err == nil {
		t.Fatal("poisoned decoder accepted input")
	}
}

func TestProtoVarintStrictness(t *testing.T) {
	r := &protoReader{data: []byte{0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0x02}}
	if _, err := r.readVarint(); err == nil {
		t.Fatal("10th varint byte > 1 accepted")
	}
	r = &protoReader{data: []byte{0x80}}
	if _, err := r.readVarint(); err == nil {
		t.Fatal("truncated varint accepted")
	}
	r = &protoReader{data: unhex(t, "fdffffffffffffffff01")}
	v, err := r.readVarint()
	if err != nil || v != uint64(0xFFFFFFFFFFFFFFFD) {
		t.Fatalf("varint = %d, %v", v, err)
	}
	// Reserved field numbers are rejected on read.
	r = &protoReader{data: appendVarint(nil, uint64(19000<<3|0))}
	if _, _, err := r.readKey(); err == nil {
		t.Fatal("reserved field number accepted")
	}
}
